import numpy as np


class RefinedFeasibilityDEPlus6:
    """
    Mixed-integer constrained DE with Deb feasibility rules, SHADE-style success-history
    adaptation of F/CR, an elite archive of good feasible points used for cloud restarts,
    and a stall-triggered incumbent pattern search (expanding continuous steps, neighbour-first
    discrete scans). The pattern-search result is injected back into the population.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng()
        dim = self.dim
        budget = self.budget

        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        vtypes = list(func.variable_types)
        disc_mask = np.array([v != "continuous" for v in vtypes], dtype=bool)
        cont_idx = np.where(~disc_mask)[0]
        disc_idx = np.where(disc_mask)[0]
        n_disc = len(disc_idx)
        n_cont = len(cont_idx)

        nvals = np.ones(dim, dtype=int)
        if n_disc > 0:
            nv_all = np.asarray(func.n_values, dtype=int)
            nvals[disc_idx] = nv_all[disc_idx]
        binary_mask = np.array([v == "binary" for v in vtypes], dtype=bool)
        cat_mask = np.array([v == "categorical" for v in vtypes], dtype=bool)
        span = np.where(ub - lb > 0, ub - lb, 1.0)

        state = {"evals": 0, "calls": 0, "best_f": np.inf, "best_x": None, "best_v": np.inf}
        cache = {}
        archive = []  # list of (f, x) feasible points, best first
        max_calls = 50 * budget
        ARCH_MAX = 10

        def done():
            return state["evals"] >= budget or state["calls"] >= max_calls

        def add_archive(f, x):
            nonlocal archive
            for fa, xa in archive:
                if np.array_equal(xa, x):
                    return
            archive.append((f, np.array(x, dtype=float, copy=True)))
            archive.sort(key=lambda t: t[0])
            if len(archive) > ARCH_MAX:
                archive = archive[:ARCH_MAX]

        def evaluate(x):
            state["calls"] += 1
            k = tuple(np.round(x, 10))
            if k in cache:
                return cache[k]
            f, g = func(x)
            state["evals"] += 1
            f = float(f)
            if not np.isfinite(f):
                f = np.inf
            g = np.asarray(g, dtype=float).ravel()
            g = np.nan_to_num(g, nan=1e6, posinf=1e6, neginf=0.0)
            viol = float(np.sum(np.maximum(g, 0.0)))
            if not np.isfinite(f):
                viol += 1.0
            if viol == 0.0 and np.isfinite(f):
                if f < state["best_f"]:
                    state["best_f"] = f
                    state["best_x"] = np.array(x, dtype=float, copy=True)
                if len(archive) < ARCH_MAX or f < archive[-1][0]:
                    add_archive(f, x)
            if viol < state["best_v"]:
                state["best_v"] = viol
            cache[k] = (f, viol)
            return f, viol

        def repair(x):
            x = x.copy()
            if n_cont:
                x[cont_idx] = np.clip(x[cont_idx], lb[cont_idx], ub[cont_idx])
            if n_disc:
                x[disc_idx] = np.clip(np.rint(x[disc_idx]), 0, nvals[disc_idx] - 1)
            return x

        def random_x():
            x = np.empty(dim)
            if n_cont:
                x[cont_idx] = rng.uniform(lb[cont_idx], ub[cont_idx])
            if n_disc:
                x[disc_idx] = rng.integers(0, nvals[disc_idx])
            return x

        def better(f1, v1, f2, v2):
            if v1 == 0.0 and v2 == 0.0:
                return f1 < f2
            if v1 == 0.0 or v2 == 0.0:
                return v1 == 0.0
            return v1 < v2

        def rank_order(F, V):
            key2 = np.where(V == 0.0, F, V)
            primary = (V > 0.0).astype(float)
            return np.lexsort((key2, primary))

        def key_of(F, V):
            b = rank_order(F, V)[0]
            return (V[b] > 0, V[b] if V[b] > 0 else F[b])

        def mutate_one(x, j):
            if binary_mask[j]:
                x[j] = 1.0 - x[j]
            elif cat_mask[j]:
                x[j] = float(rng.integers(nvals[j]))
            else:
                if rng.random() < 0.7:
                    x[j] = x[j] + (1.0 if rng.random() < 0.5 else -1.0)
                else:
                    x[j] = float(rng.integers(nvals[j]))
            return x

        def cloud_move(base, scale):
            y = base.copy()
            if n_cont:
                m = rng.random(n_cont) < 0.5
                if not m.any():
                    m[rng.integers(n_cont)] = True
                ci = cont_idx[m]
                if rng.random() < 0.25:
                    step = np.clip(rng.standard_cauchy(len(ci)), -5.0, 5.0)
                else:
                    step = rng.normal(0.0, 1.0, size=len(ci))
                y[ci] = y[ci] + scale * step * span[ci]
            if n_disc:
                p = min(1.0, 2.0 / n_disc)
                for j in disc_idx[rng.random(n_disc) < p]:
                    y = mutate_one(y, j)
            return repair(y)

        def pattern_search(x0, f0, v0):
            """Incumbent pattern search: neighbour-first discrete scans, expanding/halving continuous steps."""
            x, f, v = x0.copy(), f0, v0
            steps = np.zeros(dim)
            steps[cont_idx] = 0.1 * span[cont_idx]
            while not done():
                improved_any = False
                for j in disc_idx:
                    if done():
                        break
                    cur = int(round(x[j]))
                    if nvals[j] <= 12:
                        vals = np.arange(nvals[j])
                    else:
                        near = [cur + d for d in (-2, -1, 1, 2)]
                        near = [q for q in near if 0 <= q < nvals[j]]
                        extra = rng.choice(nvals[j], size=min(6, nvals[j]), replace=False)
                        vals = np.unique(np.concatenate([np.array(near, dtype=int), extra]))
                    for val in vals:
                        if done():
                            break
                        if float(val) == x[j]:
                            continue
                        y = x.copy()
                        y[j] = float(val)
                        fy, vy = evaluate(y)
                        if better(fy, vy, f, v):
                            x, f, v = y, fy, vy
                            improved_any = True
                for j in cont_idx:
                    if done():
                        break
                    moved = False
                    for sgn in (1.0, -1.0):
                        y = x.copy()
                        y[j] = np.clip(x[j] + sgn * steps[j], lb[j], ub[j])
                        if y[j] == x[j]:
                            continue
                        fy, vy = evaluate(y)
                        if better(fy, vy, f, v):
                            x, f, v = y, fy, vy
                            moved = True
                            improved_any = True
                            steps[j] = min(steps[j] * 1.5, 0.5 * span[j])
                            break
                    if not moved:
                        steps[j] *= 0.5
                if n_cont and not improved_any and np.max(steps[cont_idx] / span[cont_idx]) < 1e-5:
                    break
                if n_cont == 0 and not improved_any:
                    break
            return x, f, v

        def init_population(NP, elite_x=None):
            X = np.empty((NP, dim))
            for i in range(NP):
                X[i] = random_x()
            if elite_x is not None:
                X[0] = elite_x
                n_cloud = max(1, NP // 2)
                for i in range(1, n_cloud):
                    s = 10.0 ** rng.uniform(-3.0, -0.5)
                    X[i] = cloud_move(elite_x, s)
            Fo = np.full(NP, np.inf)
            Vi = np.full(NP, np.inf)
            cnt = 0
            for i in range(NP):
                if done():
                    break
                Fo[i], Vi[i] = evaluate(X[i])
                cnt = i + 1
            return X[:cnt], Fo[:cnt], Vi[:cnt]

        NP = int(np.clip(5 * dim, 20, 100))
        NP = min(NP, max(6, budget // 10))
        patience = max(15, 2 * dim)
        pm = 1.0 / max(1, n_disc)
        p_local = 0.15
        sigma = 0.1
        H = 6
        restart_idx = 0

        while not done():
            # restart seed: archive member (rotating) or incumbent, else random
            elite = None
            if archive and (restart_idx % 2 == 0 or rng.random() < 0.5):
                elite = archive[(restart_idx // 2) % len(archive)][1]
            restart_idx += 1

            X, Fo, Vi = init_population(NP, elite)
            n = len(X)
            if n < 4:
                break

            MF = np.full(H, 0.5)
            MCR = np.full(H, 0.9)
            mem_k = 0
            best_key = key_of(Fo, Vi)
            stall = 0
            ps_done_for_stall = False

            while not done():
                improved = False
                SF, SCR = [], []
                for i in range(n):
                    if done():
                        break
                    r = rng.integers(H)
                    Fi = -1.0
                    while Fi <= 0.0:
                        Fi = MF[r] + 0.1 * rng.standard_cauchy()
                    Fi = min(Fi, 1.0)
                    CRi = float(np.clip(MCR[r] + 0.1 * rng.standard_normal(), 0.0, 1.0))
                    order = rank_order(Fo, Vi)
                    best_idx = order[0]

                    use_local = state["best_x"] is not None and rng.random() < p_local
                    if use_local:
                        trial = cloud_move(state["best_x"], sigma)
                        f_t, v_t = evaluate(trial)
                        if better(f_t, v_t, Fo[i], Vi[i]):
                            X[i] = trial
                            Fo[i], Vi[i] = f_t, v_t
                            sigma = min(0.3, sigma * 1.2)
                            improved = True
                        else:
                            sigma = max(1e-4, sigma * 0.97)
                        continue

                    cands = [k for k in range(n) if k != i]
                    r1, r2, r3 = rng.choice(cands, size=3, replace=False)
                    if rng.random() < 0.5:
                        mutant = X[r1] + Fi * (X[r2] - X[r3])
                    else:
                        mutant = X[best_idx] + Fi * (X[r1] - X[r2])

                    trial = X[i].copy()
                    jrand = rng.integers(dim)
                    mask = rng.random(dim) < CRi
                    mask[jrand] = True

                    if n_cont:
                        sel = cont_idx[mask[cont_idx]]
                        trial[sel] = mutant[sel]
                    if n_disc:
                        sel_d = disc_idx[mask[disc_idx]]
                        if len(sel_d):
                            donor = X[r1] if rng.random() < 0.5 else X[best_idx]
                            trial[sel_d] = donor[sel_d]
                        mut_js = disc_idx[rng.random(n_disc) < pm]
                        for j in mut_js:
                            trial = mutate_one(trial, j)

                    trial = repair(trial)
                    f_t, v_t = evaluate(trial)
                    if better(f_t, v_t, Fo[i], Vi[i]):
                        X[i] = trial
                        Fo[i] = f_t
                        Vi[i] = v_t
                        SF.append(Fi)
                        SCR.append(CRi)

                # SHADE memory update
                if SF:
                    sf = np.asarray(SF)
                    scr = np.asarray(SCR)
                    mean_f = np.sum(sf ** 2) / max(np.sum(sf), 1e-12)
                    MF[mem_k] = 0.5 * MF[mem_k] + 0.5 * mean_f
                    MCR[mem_k] = 0.5 * MCR[mem_k] + 0.5 * np.mean(scr)
                    mem_k = (mem_k + 1) % H

                cur_key = key_of(Fo, Vi)
                if cur_key[0] < best_key[0] or (
                    cur_key[0] == best_key[0] and cur_key[1] < best_key[1] - 1e-12
                ):
                    improved = True
                    best_key = cur_key
                stall = 0 if improved else stall + 1

                if stall >= max(4, patience // 2) and not ps_done_for_stall \
                        and state["best_x"] is not None and not done():
                    ps_done_for_stall = True
                    inc = state["best_x"]
                    f_inc, v_inc = evaluate(inc)
                    xp, fp, vp = pattern_search(inc, f_inc, v_inc)
                    worst = rank_order(Fo, Vi)[-1]
                    if better(fp, vp, Fo[worst], Vi[worst]):
                        X[worst] = xp
                        Fo[worst], Vi[worst] = fp, vp
                    new_key = key_of(Fo, Vi)
                    if new_key[0] < best_key[0] or (
                        new_key[0] == best_key[0] and new_key[1] < best_key[1] - 1e-12
                    ):
                        best_key = new_key
                        stall = 0
                        ps_done_for_stall = False

                if stall >= patience:
                    break

        if state["best_x"] is None:
            return np.inf, None
        return state["best_f"], state["best_x"]
